package tn.jibli.model;

import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

// @Entity: one Order object is one row. "order" is a reserved SQL word, so the table is "orders".
@Entity
@Table(name = "orders")
public class Order {

    public static final double DELIVERY_FEE = 4.0;

    private static int createdCount = 0;

    // primary key, generated by the database
    @Id
    @GeneratedValue
    private Long id;

    private String restaurant;
    private String product;
    private double total;

    String note;

    // JPA uses this one to build objects from rows, so it does not count them
    protected Order() {
    }

    public Order(String restaurant, String product, double total) {
        setRestaurant(restaurant);
        setProduct(product);
        setTotal(total);
        createdCount++;
    }

    public static int getCreatedCount() {
        return createdCount;
    }

    static void resetCounter() {
        createdCount = 0;
    }

    public double totalWithFee() {
        return total + DELIVERY_FEE;
    }

    protected String audit() {
        return "audit: " + restaurant + "/" + product + "/" + total;
    }

    public Long getId() {
        return id;
    }

    public String getRestaurant() {
        return restaurant;
    }

    public void setRestaurant(String restaurant) {
        if (restaurant == null || restaurant.isBlank()) {
            throw new IllegalArgumentException("restaurant must not be blank");
        }
        this.restaurant = restaurant;
    }

    public String getProduct() {
        return product;
    }

    public void setProduct(String product) {
        if (product == null || product.isBlank()) {
            throw new IllegalArgumentException("product must not be blank");
        }
        this.product = product;
    }

    public double getTotal() {
        return total;
    }

    public void setTotal(double total) {
        if (total < 0) {
            throw new IllegalArgumentException("total must not be negative");
        }
        this.total = total;
    }
}
